/* Hebrew Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Noam": "pleasantness — Hebrew", "Yael": "ibex, mountain goat — Hebrew", "Eitan": "strong, enduring — Hebrew", "Tal": "dew — Hebrew", "Aviv": "spring — Hebrew", "Shira": "song, poetry — Hebrew", "Cohen": "The priestly surname, marking descent from Aaron.", "Levi": "The tribal surname of the Levites.", "Ben-Gurion": "Family name of David Ben-Gurion, Israel's founding prime minister.", "Mizrahi": "A surname meaning one from the east."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Noam';
console.log(lookup(q));

